package dev.bennett.codexmeter;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.Bundle;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;
public final class AchievementJourneyNativeTest extends Instrumentation {
    int checks;android.content.Context c;GrowthActivity a;String account;
    void check(boolean value,String text){checks++;if(!value)throw new AssertionError(text);}
    void main(Runnable r){runOnMainSync(r);waitForIdleSync();}
    void waitLoaded()throws Exception {for(int i=0;i<100;i++){final boolean[] ready={false};main(()->ready[0]=a.findViewById(R.id.dashboard_scroll).findViewWithTag("journey:switch")!=null);if(ready[0]){Thread.sleep(120);waitForIdleSync();return;}Thread.sleep(80);}throw new AssertionError("Journey UI timeout");}
    androidx.appcompat.widget.SwitchCompat toggle(){return a.findViewById(R.id.dashboard_scroll).findViewWithTag("journey:switch");}
    JSONObject state()throws Exception {return RpgProgressStore.export(c,account).getJSONObject("rpg");}
    void shot(String name,View view)throws Exception {File folder=new File(c.getExternalFilesDir(null),"rpg3-fixtures");folder.mkdirs();Bitmap b=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);view.draw(new Canvas(b));try(FileOutputStream f=new FileOutputStream(new File(folder,name))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
    void tokens(long n)throws Exception {Thread.sleep(3);long at=System.currentTimeMillis();RpgProgressStore.tokens(c,account,new JSONObject().put("account",account).put("source","codex_account_usage_v1").put("at",at).put("summary",new JSONObject().put("lifetimeTokens",n)));}
    @Override public void onCreate(Bundle b){super.onCreate(b);start();}
    @Override public void onStart(){Bundle result=new Bundle();try {
        c=getTargetContext();check(c.getPackageName().endsWith(".rpg3qa"),"Never use production account/package");AppPreferences.setAutomaticRefresh(c,false);UpdatePreferences.setAutomaticChecks(c,false);account=SubscriptionStore.accountKey(c);check(account!=null,"Existing synthetic QA account");JSONObject s=state();check(!AchievementJourney.enabled(s),"Migration defaults OFF");check(RpgGrowthFacts.earned(s).isEmpty(),"Previous automatic medals archived");long xp=s.getLong("xp");
        a=(GrowthActivity)startActivitySync(new Intent(c,GrowthActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitLoaded();main(()->check(!toggle().isChecked(),"Actual growth toggle is OFF"));main(()->toggle().performClick());Thread.sleep(120);main(()->{check(a.detailDialog!=null&&a.detailDialog.isShowing(),"Start confirmation appears");check(!toggle().isChecked(),"Not ON until confirmation");try{shot("journey-confirmation.png",a.detailDialog.getWindow().getDecorView());}catch(Exception e){throw new RuntimeException(e);}a.detailDialog.getButton(-2).performClick();});Thread.sleep(300);waitLoaded();check(AchievementJourney.journey(state()).getLong("first_started_at")==0,"Cancel does not start/count");
        main(()->toggle().performClick());Thread.sleep(100);main(()->a.detailDialog.getButton(-1).performClick());Thread.sleep(350);waitLoaded();s=state();check(AchievementJourney.enabled(s),"Actual positive button commits ON");long start=AchievementJourney.journey(s).getLong("first_started_at");String id=AchievementJourney.journey(s).getString("id");check(start>0,"Start time persisted in Android SQLite");check(s.getLong("xp")==xp,"Starting never resets XP");
        long baseline=s.getJSONObject("tokens").getJSONObject("official").optLong("lifetimeTokens",0)+100_000_000L;tokens(baseline);check(AchievementJourney.journey(state()).getLong("tokens")==0,"First live envelope remains baseline");tokens(baseline+100_000_000L);s=state();List<String> medals=RpgGrowthFacts.earned(s);check(medals.size()==3,"Only post-start 100m delta earns three token medals");
        main(()->a.load(true));Thread.sleep(350);waitLoaded();main(()->toggle().performClick());Thread.sleep(350);waitLoaded();s=state();check(!AchievementJourney.enabled(s),"Actual switch pauses");check(RpgGrowthFacts.earned(s).equals(medals),"Pausing preserves earned collection");tokens(baseline+5_000_000_000L);check(AchievementJourney.journey(state()).getLong("tokens")==100_000_000L,"Paused work cannot increase achievements");
        main(()->toggle().performClick());Thread.sleep(100);main(()->a.detailDialog.getButton(-1).performClick());Thread.sleep(350);waitLoaded();s=state();check(AchievementJourney.journey(s).getString("id").equals(id)&&AchievementJourney.journey(s).getLong("first_started_at")==start,"Resume preserves collection identity");tokens(baseline+6_000_000_000L);tokens(baseline+6_001_000_000L);check(AchievementJourney.journey(state()).getLong("tokens")==101_000_000L,"Only new resume delta added");
        main(()->a.load(true));Thread.sleep(350);waitLoaded();main(()->{try{shot("journey-active.png",a.getWindow().getDecorView());}catch(Exception e){throw new RuntimeException(e);}a.finish();});
        a=(GrowthActivity)startActivitySync(new Intent(c,GrowthActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitLoaded();main(()->{check(toggle().isChecked(),"Reopened screen keeps ON");a.finish();});check(RpgGrowthFacts.earned(state()).equals(medals),"Reopened native journal keeps earned medals");result.putString("stream","Achievement journey native: "+checks+" checks passed; isolated synthetic emulator, not user phone.\n");finish(-1,result);
    }catch(Throwable e){StringWriter w=new StringWriter();e.printStackTrace(new PrintWriter(w));result.putString("stream",w.toString());finish(0,result);}}
}
